/* Round 71, seam 1: the Greenhouse style's data models come from a static list (models/index.ts, generated by
   scripts/models-index.ts) in place of Vite's `import.meta.glob`, and style.json is imported with its JSON attribute,
   so the style's index loads in Node. This test holds the list to the folder (the same names as its .json files, each
   with that file's content, and the file's text is exactly what the generator writes, so a model added or removed
   without a regeneration fails here) and holds the seam itself: the style's index loads in Node and draws a data model. */
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import * as THREE from "three";
import { modelFiles } from "../models/index.ts";
import { modelNames, PACKAGE_ROOT, render } from "../scripts/models-index.ts";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

test("the model list names exactly the folder's .json files, each with that file's parsed content", () => {
  const files = readdirSync(path.join(ROOT, "models")).filter((file) => file.endsWith(".json"));
  assert.ok(files.length > 100, `the folder holds the models (${files.length})`);
  const names = files.map((file) => file.slice(0, -".json".length)).sort();
  assert.deepEqual([...modelFiles.keys()].sort(), names, "the list's names are the folder's files");
  for (const name of names) assert.deepEqual(modelFiles.get(name), JSON.parse(readFileSync(path.join(ROOT, "models", `${name}.json`), "utf8")), `${name}: the file's content`);
});

test("models/index.ts is exactly what the generator writes for the folder", () => {
  assert.equal(PACKAGE_ROOT, ROOT);
  const names = modelNames(ROOT);
  assert.equal(names.length, [...modelFiles.keys()].length);
  assert.equal(readFileSync(path.join(ROOT, "models", "index.ts"), "utf8"), render(names), "regenerate: node packages/style-greenhouse/scripts/models-index.ts");
});

test("the style's index loads in Node: its factory's manifest, and a style that draws a data model and a variant", async () => {
  const { greenhouseStyle } = await import("../src/index.ts");
  assert.equal(greenhouseStyle.manifest.id, "greenhouse");
  const style = greenhouseStyle.create();
  const banner = style.model("banner");
  assert.ok(banner instanceof THREE.Object3D, "banner (a data model) is drawn");
  assert.ok(banner.children.length > 0, "with its parts");
  assert.equal(style.model("no-such-model" as never), null, "an unknown key is null");
  style.dispose();
});
